Output609871790 642799661Time Complexity: O(n)Auxiliary Space: O(1)Features of Polynomial rolling hash functionCalculation of Hashes of any substring of a given string in constant timeNote that computing the hash of the string S will also compute the hashes of all of the prefixes. We just have to store the hash values of the prefixes while computing. Say \text{hash[i]} denotes the hash of the prefix \text{S[0...i]}, we have\text{hash[i...j]}\cdot p^i = \text{hash[0...j]} - \text{hash[0...(i - 1)]}This allows us to quickly compute the hash of the substring \text{S[i...j]}                  in O(1)                  provided we have powers of p                  ready.The behavior of the hash when a character is changedRecall that the hash of a string s                  is given by\text{hash(s)} = \displaystyle\sum_{i = 0}^{n - 1} s[i]\cdot p^i\quad \text{mod}\ mSay, we change a character ch1                  at some index i                  to some other character ch2                 . How will the hash change?If \text{hash\_old}                  denotes the hash value before changing and \text{hash\_new}                  is the hash value after changing, then the relation between them is given by\text{hash\_new} = \text{hash\_old} - p^i\cdot(ch1) + p^i\cdot(ch2)Therefore, queries can be performed very quickly instead of recalculating the hash from beginning, provided we have the powers of p                  ready.Below is given the implementation:
            C++

    #include <bits/stdc++.h>
using namespace std;
#define int long long

// Function to calculate power
int power(int x, int y, int p) {
    int result = 1;
    for(; y; y >>= 1, x = x * x % p) {
        if(y & 1) {
            result = result * x % p;
        }
    }
    return result;
}

// Function to calculate inverse
int inverse(int x, int p) {
    return power(x, p - 2, p);
}

// Function to precompute inverse powers
void preCompute(int len, int p, int mod, vector<int>& invPow) {

    int invSize = 1;
    while(invSize < len) {
        invSize <<= 1;
    }

    invPow.resize(invSize, -1);
    invPow[invSize - 1] = 
    inverse(power(p, invSize - 1, mod), mod);

    for(int i = invSize - 2; i >= 0 
        && invPow[i] == -1; i--) {
        invPow[i] = (1LL * invPow[i + 1] * p) % mod;
    }
}

// Function to compute hash values of a string
pair<vector<int>, vector<int>> computeHashes(
    string& s, int p1, int p2, int mod1, int mod2, 
    vector<int>& invPow1, vector<int>& invPow2) {
    int len = s.size();
    vector<int> hash1(len), hash2(len);

    int h1 = 0, h2 = 0;
    int pPow1 = 1, pPow2 = 1;

    for(int i = 0; i < len; i++) {
        h1 = (h1 + (s[i] - 'a' + 1) * pPow1) % mod1;
        h2 = (h2 + (s[i] - 'a' + 1) * pPow2) % mod2;
        pPow1 = (pPow1 * p1) % mod1;
        pPow2 = (pPow2 * p2) % mod2;
        hash1[i] = h1;
        hash2[i] = h2;
    }

    preCompute(len, p1, mod1, invPow1);
    preCompute(len, p2, mod2, invPow2);

    return {hash1, hash2};
}

// Function to compute hash of a substring
pair<int, int> getSubstringHash(vector<int>& hash1, 
    vector<int>& hash2, int l, int r, vector<int>& invPow1, 
    vector<int>& invPow2, int mod1, int mod2) {

    if(l == 0) {
        return {hash1[r], hash2[r]};
    }

    int temp1 = hash1[r] - hash1[l - 1];
    int temp2 = hash2[r] - hash2[l - 1];

    temp1 += (temp1 < 0 ? mod1 : 0);
    temp2 += (temp2 < 0 ? mod2 : 0);
    temp1 = (temp1 * 1LL * invPow1[l]) % mod1;
    temp2 = (temp2 * 1LL * invPow2[l]) % mod2;

    return {temp1, temp2};
}

// Function to process the string and compute hashes
pair<int, int> findHash(string &str) {
    int n = str.length();

    int mod1 = 1e9 + 7, mod2 = 1e9 + 9;
    int p1 = 31, p2 = 37;

    vector<int> invPow1, invPow2;
    pair<vector<int>, vector<int>> hashes = 
    computeHashes(str, p1, p2, mod1, mod2, invPow1, invPow2);
    auto hashPair = getSubstringHash(hashes.first, 
    hashes.second, 0, n - 1, invPow1, invPow2, mod1, mod2);

    return hashPair;

}

signed main() {
    string str = "geeksforgeeks";
    pair<int, int> hashPair = findHash(str);
    cout << hashPair.first << " " << hashPair.second;
    return 0;
}


