        long temp2 = (hash2.get(r) - hash2.get(l - 1) + mod2) % mod2;
        temp1 = (temp1 * invPow1.get(l)) % mod1;
        temp2 = (temp2 * invPow2.get(l)) % mod2;

        return new Pair<>(temp1, temp2);
    }

